// Auto-generated from the files under firebase/ by tsup.config.ts. Do not edit.
// Edit firebase/firestore.rules, firebase/storage.rules, or
// firebase/firestore.indexes.json instead, then run `npm run build`.

export const CASPIAN_FIRESTORE_RULES = "rules_version = '2';\nservice cloud.firestore {\n  match /databases/{database}/documents {\n\n    // Admin signal — claim-first, Firestore fallback. The Firebase Auth\n    // custom claim `role` is the primary admin signal as of v8.4.1; the\n    // Firestore read is a fallback for admins promoted before v8.4.1 (or\n    // before their token has rotated to pick up the new claim). Storage\n    // rules check the same predicate so consumer admin authorization\n    // works identically across services.\n    function isAdmin() {\n      return request.auth != null\n          && (request.auth.token.role == 'admin'\n              || (exists(/databases/$(database)/documents/users/$(request.auth.uid))\n                  && get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role == 'admin'));\n    }\n\n    function isAuth() {\n      return request.auth != null;\n    }\n\n    // Staff signal (v10.0.0) — the POS cashier role. Same claim-first,\n    // Firestore-fallback shape as isAdmin(), and deliberately inclusive of\n    // 'admin': an owner working the counter must not need a second account.\n    // Staff reach the register at /pos and read the catalog; they are denied\n    // every admin surface (AdminGuard still requires 'admin') and every\n    // settings write. `syncUserRoleClaim` mirrors users/{uid}.role onto the\n    // Auth custom claim so the fast path needs no document read.\n    function isStaff() {\n      return request.auth != null\n          && (request.auth.token.role in ['staff', 'admin']\n              || (exists(/databases/$(database)/documents/users/$(request.auth.uid))\n                  && get(/databases/$(database)/documents/users/$(request.auth.uid)).data.role in ['staff', 'admin']));\n    }\n\n    match /products/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /productCategories/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /productBrands/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    // Generic product-taxonomy terms (materials, seasons, colors, …). Public\n    // read so the storefront can filter/display; admin-only write. Same posture\n    // as productCategories / productBrands.\n    match /taxonomyTerms/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /productCollections/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    // Orders. The only client-side writer is the manual-payment path\n    // (src/payments/plugins/manual-base.ts), which records the shopper's\n    // intent to pay by bank transfer / cheque / cash on delivery. Everything\n    // else — Stripe, the register — is written by Cloud Functions through the\n    // Admin SDK. So a client create is pinned to that one shape: own userId,\n    // `on-hold` (never `paid`), a manual payment method, a non-empty items\n    // list, non-negative money fields and no `channel` (that field marks a\n    // POS sale). Without this, any signed-in or anonymous session could write\n    // a `paid` order for any userId/email, which shows as paid in admin and\n    // fires the merchant + customer emails.\n    match /orders/{id} {\n      allow read: if isAdmin() || (isAuth() && resource.data.userId == request.auth.uid);\n      allow create: if isAuth()\n                    && request.resource.data.userId == request.auth.uid\n                    && request.resource.data.status == 'on-hold'\n                    && request.resource.data.payment.method in ['bacs', 'cheque', 'cod']\n                    && request.resource.data.items is list\n                    && request.resource.data.items.size() > 0\n                    && !('channel' in request.resource.data)\n                    && request.resource.data.subtotal is number\n                    && request.resource.data.subtotal >= 0\n                    && request.resource.data.total is number\n                    && request.resource.data.total >= 0;\n      allow update: if isAdmin();\n    }\n\n    // Server-side checkout state for Stripe (functions-stripe). The callable\n    // writes the priced cart + shipping address here instead of into Stripe\n    // session metadata (500-char cap per value — two items with image URLs\n    // already overflow it), and the webhook reads it back to build the order.\n    // Cloud Functions use the Admin SDK, which bypasses rules; no client ever\n    // needs this collection, so deny everything.\n    match /pendingCheckouts/{id} {\n      allow read, write: if false;\n    }\n\n    // Idempotency markers for delivered Stripe webhook events, created inside\n    // the order-writing transaction so a concurrent redelivery fails fast\n    // instead of writing a second order and decrementing stock twice.\n    // Server-only for the same reason as pendingCheckouts.\n    match /stripeEvents/{id} {\n      allow read, write: if false;\n    }\n\n    match /users/{uid} {\n      allow read: if isAuth() && request.auth.uid == uid;\n      // On create: a user can write their own profile; role must be absent\n      // or explicitly 'customer'. This is the only path — on first sign-in\n      // resource.data is null, so the update-rule's role-equality check\n      // (request.resource.data.role == resource.data.role) would fail\n      // against null and silently deny the write, leaving userProfile null\n      // in auth-context and every profile-dependent UI card blank.\n      allow create: if isAuth() && request.auth.uid == uid\n                    && (!('role' in request.resource.data) || request.resource.data.role == 'customer');\n      // On update: role must stay as it is on the existing doc — blocks\n      // self-promotion. Admin writes go through the isAdmin() branch below.\n      allow update: if isAuth() && request.auth.uid == uid\n                    && (!('role' in request.resource.data) || request.resource.data.role == resource.data.role);\n      // \"Delete my account\" removes the Auth user client-side; without this\n      // the profile doc (name, addresses, email) was orphaned as PII.\n      allow delete: if isAuth() && request.auth.uid == uid;\n      allow read, write: if isAdmin();\n    }\n\n    match /carts/{uid} {\n      // Owner reads/writes their own cart. Admins may READ any cart so the\n      // admin user-detail view can show what a shopper currently has in their\n      // bag; admins never write someone else's cart.\n      allow read: if isAuth() && (request.auth.uid == uid || isAdmin());\n      allow write: if isAuth() && request.auth.uid == uid;\n    }\n\n    match /reviews/{id} {\n      allow read: if resource.data.status == 'approved' || isAdmin();\n      allow create: if isAuth()\n        && request.resource.data.userId == request.auth.uid\n        && request.resource.data.status == 'pending'\n        && request.resource.data.rating is number\n        && request.resource.data.rating >= 1\n        && request.resource.data.rating <= 5\n        // The \"verified purchase\" badge is stamped server-side by the\n        // functions-admin `stampVerifiedPurchase` trigger after it checks the\n        // reviewer's orders. A client may only write `false` (or nothing) —\n        // otherwise the badge is a free-text claim anyone can make.\n        && (!('isVerifiedPurchase' in request.resource.data)\n            || request.resource.data.isVerifiedPurchase == false);\n      allow update, delete: if isAdmin();\n    }\n\n    match /questions/{id} {\n      allow read: if resource.data.status == 'approved' || isAdmin();\n      allow create: if isAuth()\n        && request.resource.data.userId == request.auth.uid\n        && request.resource.data.status == 'pending';\n      allow update, delete: if isAdmin();\n    }\n\n    // Promo codes. Shoppers never read this collection: the cart page only\n    // stashes the typed code, the Stripe callable validates it server-side and\n    // the manual-payment flows apply no discount at all. `isAuth()` read let\n    // any anonymous session enumerate every live code. Staff keep read so a\n    // till can show a discount before the server-side commit re-validates it.\n    match /promoCodes/{id} {\n      allow read: if isStaff();\n      allow write: if isAdmin();\n    }\n\n    // Shipping plugin installs — public read so the checkout calculator and\n    // the public /shipping page can enumerate offered methods. Admin-only\n    // write prevents shoppers from tampering with pricing.\n    match /shippingPluginInstalls/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    // Payment plugin installs — public read so `useCheckout` on the storefront\n    // can discover which provider to invoke. Only publishable (`pk_`-style)\n    // credentials live here; server-side secrets are Cloud Functions secrets.\n    // Admin-only write prevents shoppers from tampering with enabled providers.\n    match /paymentPluginInstalls/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    // Email plugin installs — admin-only read AND write. Records which\n    // provider (SendGrid / Brevo) is enabled; since v8.0.0 the API key itself\n    // is a Cloud Functions secret (CASPIAN_EMAIL_<PROVIDER>_API_KEY), not a\n    // field here. Cloud Functions read via the Admin SDK, which bypasses\n    // rules. Shoppers never need to see this collection, unlike\n    // shipping/payment installs. Added in v2.14.\n    match /emailPluginInstalls/{id} {\n      allow read: if isAdmin();\n      allow write: if isAdmin();\n    }\n\n    // Instagram channel connection — server-only. The single `instagram/connection`\n    // doc holds the IG Business account id and the access tokens (long-lived user\n    // token + Page token), written/read only by the functions-instagram Cloud\n    // Functions (Admin SDK, which bypasses rules). These are secrets, so deny ALL\n    // client access. Clients (the admin panel and the register) talk to the\n    // callables, which return connection status + feed + comments — never a token.\n    match /instagram/{id} {\n      allow read, write: if false;\n    }\n\n    match /faqs/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /journal/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /pageContents/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    // Page builder (v9.26.0). PUBLISHED layouts are public-read (the storefront\n    // renders from them), admin-write; their `revisions` subcollection is\n    // admin-only history. WORKING DRAFTS and publish SCHEDULES are admin-only\n    // read AND write, so unpublished content never leaks. `builderPages` is the\n    // public-read custom-page registry (drafts hidden in app code, not rules).\n    match /pageLayouts/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n      match /revisions/{version} {\n        allow read, write: if isAdmin();\n      }\n    }\n    match /pageLayoutDrafts/{id} {\n      allow read, write: if isAdmin();\n    }\n    match /pageLayoutSchedules/{id} {\n      allow read, write: if isAdmin();\n    }\n    match /builderPages/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /languages/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    // Newsletter signups. The doc id is `encodeURIComponent(email)` (see\n    // src/services/subscriber-service.ts) so a second signup for the same\n    // address is an update, which is denied — that denial is the client's\n    // \"already subscribed\" signal. Because the id is encoded it cannot be\n    // compared to the email field here; the shape gate is what keeps a\n    // public create from stuffing arbitrary fields into the collection.\n    match /subscribers/{id} {\n      allow create: if id.size() > 0\n                    && request.resource.data.keys().hasOnly(['email', 'subscribedAt'])\n                    && request.resource.data.email is string\n                    && request.resource.data.email.size() > 0\n                    && request.resource.data.email.size() <= 320;\n      allow read, delete: if isAdmin();\n    }\n\n    // Contact-form submissions (v2.13). Public create so unauthenticated\n    // visitors can send a message; shape + length clamps blunt spam/abuse.\n    // Admin-only read/update/delete — submissions are never shown publicly.\n    // `status` is pinned to 'new' on create so the bell badge counts\n    // everything that comes in; admins flip to 'read'/'archived'.\n    match /contacts/{id} {\n      allow create: if request.resource.data.status == 'new'\n                    && request.resource.data.name is string\n                    && request.resource.data.name.size() > 0\n                    && request.resource.data.name.size() <= 120\n                    && request.resource.data.email is string\n                    && request.resource.data.email.size() > 0\n                    && request.resource.data.email.size() <= 200\n                    && request.resource.data.message is string\n                    && request.resource.data.message.size() > 0\n                    && request.resource.data.message.size() <= 5000\n                    && (!('subject' in request.resource.data)\n                        || (request.resource.data.subject is string\n                            && request.resource.data.subject.size() <= 200));\n      allow read, update, delete: if isAdmin();\n    }\n\n    // Search-term analytics — storefront visitors upsert a doc per\n    // normalized query (count + timestamps). Admin-only read/delete.\n    // Shape is validated but writes are public: the data is analytics,\n    // not security-sensitive, and forcing auth would drop anonymous\n    // shoppers out of the funnel.\n    match /searchTerms/{id} {\n      allow read, delete: if isAdmin();\n      allow create: if request.resource.data.term is string\n                    && request.resource.data.term.size() > 0\n                    && request.resource.data.term.size() <= 200\n                    && request.resource.data.count == 1;\n      // One search = one increment. `count > resource.count` let a visitor\n      // set any count in a single write; only `count` and `lastSearchedAt`\n      // may change so `term`/`firstSearchedAt` cannot be rewritten either.\n      allow update: if request.resource.data.diff(resource.data).affectedKeys()\n                        .hasOnly(['count', 'lastSearchedAt'])\n                    && request.resource.data.count is number\n                    && request.resource.data.count == resource.data.count + 1;\n    }\n\n    match /settings/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    match /scriptSettings/{id} {\n      allow read: if true;\n      allow write: if isAdmin();\n    }\n\n    // Admin todo list — admins only for both read and write. Contains\n    // internal setup/operational tasks, not shopper-facing content.\n    match /adminTodos/{id} {\n      allow read: if isAdmin();\n      allow write: if isAdmin();\n    }\n\n    // Setup-wizard email allowlist for the very first admin (v8.7.0).\n    // Doc id is the lowercase, trimmed email. The wizard's \"Designate by\n    // email\" path writes here BEFORE any admin exists; once the named\n    // user signs up, `onUserCreate` promotes them and deletes the doc.\n    //\n    // - Public read so the wizard can confirm a designation already exists.\n    // - Public create — but a doc can only be written ONCE per email\n    //   (`!exists`), shape is validated, and the email must equal the\n    //   doc id. The bigger safety invariant (\"no admin exists yet\") is\n    //   enforced server-side in `onUserCreate`: if an admin already\n    //   exists, the trigger ignores all pending entries, so a stale\n    //   write here can't escalate privilege.\n    // - Update forbidden — re-designate by delete + recreate.\n    // - Delete restricted to admins (so post-install revocation goes\n    //   through the admin panel; pre-install installers who fat-finger\n    //   the email can fix it by signing up under the typo'd address\n    //   to consume the entry, or by simply typing it correctly the\n    //   second time — distinct emails create distinct docs).\n    match /pendingSuperAdmin/{email} {\n      allow read: if true;\n      allow create: if !exists(/databases/$(database)/documents/pendingSuperAdmin/$(email))\n                    && request.resource.data.keys().hasOnly(['email', 'designatedAt'])\n                    && request.resource.data.email is string\n                    && request.resource.data.email.size() > 0\n                    && request.resource.data.email.size() <= 320\n                    && request.resource.data.email == email;\n      allow delete: if isAdmin();\n    }\n\n    // Transactional email config (v2.11). Admin-only on both read and write —\n    // contains sender addresses, admin recipient lists, and unfiltered\n    // template bodies that shouldn't leak to shoppers. Cloud Functions\n    // bypass rules via the Admin SDK.\n    match /emailSettings/{id} {\n      allow read: if isAdmin();\n      allow write: if isAdmin();\n    }\n    match /emailTemplates/{id} {\n      allow read: if isAdmin();\n      allow write: if isAdmin();\n    }\n\n    // Error logs (mod1182). Writes are public because crashes happen in\n    // unauthenticated shopper sessions too — gate abuse with a strict shape\n    // check (required scalar fields, capped string lengths, fixed source\n    // enum, forbidden admin fields). Reads, updates, and deletes are\n    // admin-only: the panel at /admin/about lists them, the admin dismisses\n    // them, and the scheduled retention sweep trims them. Cloud Functions\n    // write via the Admin SDK which bypasses rules entirely.\n    match /errorLogs/{id} {\n      allow create: if request.resource.data.source in ['client', 'service', 'cloud-function']\n                    && request.resource.data.origin is string\n                    && request.resource.data.origin.size() > 0\n                    && request.resource.data.origin.size() <= 200\n                    && request.resource.data.message is string\n                    && request.resource.data.message.size() > 0\n                    && request.resource.data.message.size() <= 2000\n                    && (!('stack' in request.resource.data)\n                        || (request.resource.data.stack is string\n                            && request.resource.data.stack.size() <= 4000))\n                    && request.resource.data.libraryVersion is string\n                    && request.resource.data.libraryVersion.size() <= 40\n                    && request.resource.data.seenCount == 1;\n      allow read, update, delete: if isAdmin();\n    }\n\n    // --- Point of sale (v10.0.0) ---\n\n    // Till sessions. Written ONLY by the caspian-pos Cloud Functions via the\n    // Admin SDK (which bypasses rules), never from the register — otherwise a\n    // cashier could edit `expectedCash` to paper over a drawer variance.\n    // Staff read so the register can show its own open shift and the X-report.\n    match /posSessions/{id} {\n      allow read: if isStaff();\n      allow write: if false;\n    }\n\n    // Register registry: one document per physical till / browser profile.\n    // Staff read (the register resolves its own label + saved locale on boot);\n    // admins name and retire registers from the admin panel.\n    match /posDevices/{id} {\n      allow read: if isStaff();\n      allow write: if isAdmin();\n    }\n\n    // Monotonic receipt-number counter (`posCounters/receipt`). Server-only on\n    // both sides: allocation happens inside the commitPosSale transaction, and\n    // a client that could read it would learn the store's total sale count.\n    match /posCounters/{id} {\n      allow read, write: if false;\n    }\n\n    // Sold per-computer POS licenses. Server-only: `activatePosLicense` binds a\n    // key to the first deviceId that presents it, and the documents carry\n    // customer contact details. A register learns its own status from the\n    // callable's response, never by reading the collection.\n    match /posLicenses/{id} {\n      allow read, write: if false;\n    }\n\n    // Blocks of receipt numbers reserved by leasePosReceiptBlock so a till can\n    // print a real receipt number while offline, and the claim registry that\n    // makes a number impossible to issue twice. Server-only on both sides: the\n    // register learns its block from the callable response and never reads the\n    // collection. Unlisted paths already deny, so these blocks are documentation\n    // as much as enforcement -- deploying them changes no behaviour.\n    match /posReceiptLeases/{id} {\n      allow read, write: if false;\n    }\n\n    match /posReceiptNumbers/{id} {\n      allow read, write: if false;\n    }\n  }\n}\n";

export const CASPIAN_STORAGE_RULES = "rules_version = '2';\n\n// Recommended Storage rules for a Caspian Store installation. Deploy with\n//   firebase deploy --only storage\nservice firebase.storage {\n  match /b/{bucket}/o {\n\n    // Admin signal — claim-first, Firestore fallback. v8.4.1 introduced an\n    // Auth custom claim `role` so this rule can authorize without a\n    // cross-service Firestore read; the read is kept as a fallback so\n    // admins promoted before v8.4.1 (or via the legacy grant-admin script\n    // before it was updated) are still recognized while their token rotates.\n    // The custom claim is set by the `claimAdmin` callable, the\n    // `onUserCreate` trigger, and the `syncAdminClaim` Firestore trigger\n    // that reconciles the claim with `users/{uid}.role` on every write.\n    function isAdmin() {\n      return request.auth != null\n          && (request.auth.token.role == 'admin'\n              || firestore.get(\n                   /databases/(default)/documents/users/$(request.auth.uid)\n                 ).data.role == 'admin');\n    }\n\n    // Profile avatars live under users/{uid}/<filename>. Storage rules grammar\n    // doesn't allow wildcards inside a segment, so we match any single-segment\n    // filename; the content-type + size guards below do the real validation.\n    // Anyone can read (product pages show avatars in review cards).\n    match /users/{uid}/{filename} {\n      allow read: if true;\n      allow write: if request.auth != null\n                   && request.auth.uid == uid\n                   && request.resource.size < 5 * 1024 * 1024\n                   && request.resource.contentType.matches('image/(jpeg|png|webp)');\n      allow delete: if request.auth != null && request.auth.uid == uid;\n    }\n\n    // Journal cover images — public read, admin write up to 10 MB.\n    match /journal/{path=**} {\n      allow read: if true;\n      allow write: if isAdmin()\n                   && request.resource.size < 10 * 1024 * 1024\n                   && request.resource.contentType.matches('image/(jpeg|png|webp|gif)');\n      allow delete: if isAdmin();\n    }\n\n    // Page content assets (optional image uploads from <AdminPagesPage>).\n    match /pageContents/{path=**} {\n      allow read: if true;\n      allow write: if isAdmin()\n                   && request.resource.size < 10 * 1024 * 1024\n                   && request.resource.contentType.matches('image/(jpeg|png|webp|gif)');\n      allow delete: if isAdmin();\n    }\n\n    // Site-settings branding assets — logo and favicon uploaded from\n    // <AdminSiteSettingsPage>. Public read (the storefront renders the logo\n    // on every page), admin write up to 10 MB. SVG is allowed here because\n    // logos/favicons are commonly vector.\n    match /siteSettings/{path=**} {\n      allow read: if true;\n      allow write: if isAdmin()\n                   && request.resource.size < 10 * 1024 * 1024\n                   && request.resource.contentType.matches('image/(jpeg|png|webp|gif|svg\\\\+xml)');\n      allow delete: if isAdmin();\n    }\n\n    // Product catalog images uploaded from <AdminProductEditor>. Public read\n    // (every PLP/PDP card shows these), admin write up to 10 MB. No SVG here\n    // — product photos should be raster, and blocking SVG avoids embedded-\n    // script exploits from less-trusted sources.\n    match /products/{path=**} {\n      allow read: if true;\n      allow write: if isAdmin()\n                   && request.resource.size < 10 * 1024 * 1024\n                   && request.resource.contentType.matches('image/(jpeg|png|webp|gif)');\n      allow delete: if isAdmin();\n    }\n\n    // Category featured images uploaded from <AdminCategoryEditor>. Public read\n    // (the homepage featured-categories section + header mega-menu render them),\n    // admin write up to 10 MB. No SVG — these are photos.\n    match /categories/{path=**} {\n      allow read: if true;\n      allow write: if isAdmin()\n                   && request.resource.size < 10 * 1024 * 1024\n                   && request.resource.contentType.matches('image/(jpeg|png|webp|gif)');\n      allow delete: if isAdmin();\n    }\n  }\n}\n";
